# Rule: Find the color that appears in TWO separate connected components. 
# Replace ALL other non-zero colors with that repeated color.
def transform(grid):
    # Find all connected components and their colors
    visited = set()
    components = []  # list of (color, set of positions)

    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] != 0 and (r, c) not in visited:
                color = grid[r][c]
                comp = set()
                stack = [(r, c)]
                while stack:
                    rr, cc = stack.pop()
                    if (rr, cc) in visited or grid[rr][cc] != color:
                        continue
                    visited.add((rr, cc))
                    comp.add((rr, cc))
                    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nr, nc = rr + dr, cc + dc
                        if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                            if (nr, nc) not in visited and grid[nr][nc] == color:
                                stack.append((nr, nc))
                components.append((color, comp))

    # Count how many components of each color
    color_counts = {}
    for color, comp in components:
        color_counts[color] = color_counts.get(color, 0) + 1

    # Find the color with count == 2 (the repeated shape)
    repeated_color = None
    for color, cnt in color_counts.items():
        if cnt == 2:
            repeated_color = color
            break

    # Replace all non-zero cells with repeated_color (or keep original if no repeated color)
    result = [row[:] for row in grid]
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] != 0:
                result[r][c] = repeated_color

    return result

